	vma_start_write(middle);

	if (merge_right) {
		vma_start_write(next);
		vmg->target = next;
		sticky_flags |= (next->vm_flags & VM_STICKY);
	}

	if (merge_left) {
		vma_start_write(prev);
		vmg->target = prev;
		sticky_flags |= (prev->vm_flags & VM_STICKY);
	}

