		vmg->target = prev;
		vmg->start = prev->vm_start;
		vmg->pgoff = prev->vm_pgoff;

		if (!merge_will_delete_middle) {
			adjust = middle;
			adj_start = vmg->end - middle->vm_start;
		}

		err = dup_anon_vma(prev, middle, &anon_dup);
	} else { /* merge_right */
		/*
